   175|function readEvidenceFromSource(file: string, source: string): IVXRuntimeV2SourceInspection['evidence'] {
   176|  if (file.endsWith('ivx-owner-ai-intent-router.ts')) {
   177|    return {
   178|      hasPrioritizedBugListRouting: source.includes('prioritized\\s+bug\\s+list') || source.includes('prioritized bug list'),
   179|      hasAmbiguousLocationGuard: source.includes('ambiguous_where_are_we'),
   180|      hasTimeGuardSeparatedFromLocation: source.includes('resolveOwnerLocationClarificationIntent(normalized)'),
   181|      hasExplicitToolGate: source.includes('explicitlyNeedsLiveTools'),
   182|      sourceLength: source.length,
   183|    };
   184|  }
   185|
   186|  if (file.endsWith('ivx-owner-ai.ts')) {
   187|    return {
   188|      hasRuntimeV2ResponseMetadata: source.includes('runtimeV2: internalMetadata.runtimeV2'),
   189|      idempotentReplayIncludesRuntimeV2: /existingAIRequest\\?\\.status[\\s\\S]{0,1800}runtimeV2/.test(source),
   190|      errorCatchIncludesRuntimeV2: /catch \\(error\\)[\\s\\S]{0,500}runtimeV2/.test(source),
   191|      fallbackUsedFalseOnGenericPath: source.includes('fallbackUsed: false'),
   192|      sourceLength: source.length,
   193|    };
   194|  }
   195|
   196|  if (file.endsWith('ivx-ai-runtime.ts')) {
   197|    return {
   198|      reportsAgentRuntimeV2Phase: source.includes("phase: 'agent_runtime_v2'"),
   199|      defaultModelIsGpt4oMini: source.includes("DEFAULT_IVX_AI_MODEL = 'gpt-4o-mini'"),
   200|      throwsOnEmptyResponse: source.includes('returned an empty response'),
   201|      sourceLength: source.length,
   202|    };
   203|  }
   204|
   205|  if (file.endsWith('ivxAIRequestService.ts')) {
   206|    return {
   207|      preservesRuntimeV2Payload: source.includes('runtimeV2: data?.runtimeV2 ?? null'),
   208|      hasProviderFallbackType: source.includes("'provider_fallback'"),
   209|      blocksVisibleFallbackText: source.includes('containsBlockedOwnerAIResponseText'),
   210|      frontendDefaultModelIsGpt4oMini: source.includes("DEFAULT_IVX_OWNER_AI_MODEL = 'gpt-4o-mini'"),
   211|      sourceLength: source.length,
   212|    };
   213|  }
   214|
   215|  if (file.endsWith('cto-dashboard.tsx')) {
   216|    return {
   217|      hasIVXAIStatusCard: source.includes('cto-ivx-ai-status-card'),
