   228|async function inspectSourceFiles(): Promise<IVXRuntimeV2SourceInspection[]> {
   229|  const inspections: IVXRuntimeV2SourceInspection[] = [];
   230|  for (const file of SOURCE_FILES) {
   231|    try {
   232|      const source = await readFile(path.join(SERVER_ROOT, file), 'utf8');
   233|      inspections.push({
   234|        file,
   235|        ok: true,
   236|        bytes: Buffer.byteLength(source, 'utf8'),
   237|        evidence: readEvidenceFromSource(file, source),
   238|        error: null,
   239|      });
   240|    } catch (error) {
   241|      inspections.push({
   242|        file,
   243|        ok: false,
   244|        bytes: 0,
   245|        evidence: {},
   246|        error: safeMessage(error),
   247|      });
   248|    }
   249|  }
   250|  return inspections;
   251|}
