   259|  const backend = evidenceFor(inspections, 'ivx-owner-ai.ts');
   260|  const runtime = evidenceFor(inspections, 'ivx-ai-runtime.ts');
   261|  const frontend = evidenceFor(inspections, 'ivxAIRequestService.ts');
