   280|      evidence: [
   281|        `backend.hasRuntimeV2ResponseMetadata=${String(backend.hasRuntimeV2ResponseMetadata)}`,
   282|        `backend.idempotentReplayIncludesRuntimeV2=${String(backend.idempotentReplayIncludesRuntimeV2)}`,
   283|      ],
   284|      impact: 'If a repeated request hits a completed ai_requests row, the user may see an answer without current planner/task-tree/memory state, weakening raw proof.',
   285|      recommendedFix: 'Attach a fresh runtimeV2 envelope to idempotent replay responses before returning cached answer text.',
   286|    },
   287|    {
   288|      priority: 'P1',
   289|      status: backend.errorCatchIncludesRuntimeV2 === true ? 'verified_present' : 'open',
   290|      title: 'Failure responses still do not carry a Runtime v2 failure envelope.',
   291|      evidence: [
   292|        `backend.errorCatchIncludesRuntimeV2=${String(backend.errorCatchIncludesRuntimeV2)}`,
   293|        `backend.fallbackUsedFalseOnGenericPath=${String(backend.fallbackUsedFalseOnGenericPath)}`,
