   298|    {
   299|      priority: 'P2',
   300|      status: frontend.hasProviderFallbackType === true ? 'open' : 'verified_present',
   301|      title: 'Frontend still contains provider-fallback/local-app-brain paths that can confuse proof if ever selected.',
   302|      evidence: [
