   307|      recommendedFix: 'Keep fallback masking disabled; when fallback paths are hit, render them as explicit backend/tool failure state, never assistant answer text.',
   308|    },
   309|    {
   310|      priority: 'P2',
   311|      status: runtime.defaultModelIsGpt4oMini === true || frontend.frontendDefaultModelIsGpt4oMini === true ? 'open' : 'verified_present',
   312|      title: 'Some default model constants still point to gpt-4o-mini while owner requirement is GPT-4o conversational behavior.',
   313|      evidence: [
   314|        `runtime.defaultModelIsGpt4oMini=${String(runtime.defaultModelIsGpt4oMini)}`,
   315|        `frontend.frontendDefaultModelIsGpt4oMini=${String(frontend.frontendDefaultModelIsGpt4oMini)}`,
   316|      ],
   317|      impact: 'Backend Owner AI currently defaults to GPT-4o, but fallback/runtime wrappers could degrade answer quality if those paths are activated.',
   318|      recommendedFix: 'Standardize owner-facing Runtime v2 conversational model selection to gpt-4o and keep mini only for explicit low-cost probes.',
   319|    },
   320|    {
   321|      priority: 'P2',
   322|      status: dashboard.hasRuntimeV2Tile === true && dashboard.hasLiveActivityTile === true ? 'verified_present' : 'open',
   323|      title: 'CTO dashboard shows Runtime v2 status, but not yet the full per-job Runtime v2 execution tree/log artifact.',
   324|      evidence: [
   325|        `dashboard.hasIVXAIStatusCard=${String(dashboard.hasIVXAIStatusCard)}`,
   326|        `dashboard.hasRuntimeV2Tile=${String(dashboard.hasRuntimeV2Tile)}`,
   327|        `dashboard.hasLiveActivityTile=${String(dashboard.hasLiveActivityTile)}`,
   328|      ],
   329|      impact: 'The dashboard proves Runtime v2 readiness and live activity, but the owner still needs a job-detail panel for task tree, retry logs, chunks, and final audit artifact.',
   330|      recommendedFix: 'Add a Runtime v2 job detail drawer fed by the audit/job proof contract.',
