   332|    {
   333|      priority: 'P3',
   334|      status: 'open',
   335|      title: 'Streaming is implemented as a chunking contract/proof, not yet a dedicated SSE or incremental mobile rendering pipeline.',
   336|      evidence: [
   337|        'runtimeV2.streaming.supported=true',
   338|        'this execution loop writes ordered chunks to audit proof',
   339|      ],
   340|      impact: 'Long answers can be preserved and chunked in the runtime proof, but the chat UI still needs first-class streamed rendering for very long responses.',
   341|      recommendedFix: 'Add a streaming endpoint or chunk polling contract for Runtime v2 responses and render chunks progressively in chat.',
