   346|function buildFinalResult(findings: IVXRuntimeV2BugFinding[]): string {
   347|  const header = [
   348|    'Runtime v2 execution result: prioritized IVX AI chat behavior bug list.',
   349|    '',
   350|    'Scope: safe read-only inspection of the Owner AI router, backend Owner AI handler, AI runtime wrapper, Expo request service, and CTO dashboard Runtime v2 card. No deploy, delete, production write, migration, or data mutation was performed.',
   351|    '',
   352|    'Priority scale: P0 blocks correct assistant behavior; P1 weakens proof/state visibility; P2 causes quality or dashboard gaps; P3 is follow-up architecture work.',
   353|    '',
   354|  ].join('\n');
   355|
   356|  const body = findings.map((finding, index) => [
   357|    `${index + 1}. [${finding.priority}] ${finding.title}`,
   358|    `   Status: ${finding.status}`,
   359|    `   Evidence: ${finding.evidence.join(' | ')}`,
   360|    `   Impact: ${finding.impact}`,
   361|    `   Recommended fix: ${finding.recommendedFix}`,
   362|  ].join('\n')).join('\n\n');
   363|
   364|  const footer = [
   365|    '',
   366|    'Execution notes:',
   367|    '- Planner produced a Runtime v2 task tree before worker execution.',
   368|    '- Memory/state was stored in the local audit artifact and in-process agent memory.',
   369|    '- Worker executed read-only source inspection steps only.',
   370|    '- Retry was proven with a controlled transient read-only probe failure and successful retry.',
   371|    '- Long output was split into ordered chunks in the audit proof instead of being replaced with a canned fallback.',
   372|    '- Dashboard verification is based on actual CTO dashboard source markers/testIDs.',
   373|    '- Fallback masking remained disabled; failures are represented as state/logs, not fake assistant answers.',
   374|  ].join('\n');
