   379|function chunkText(text: string, maxCharacters: number): Array<{ index: number; total: number; characters: number; text: string }> {
   380|  const safeMax = Math.max(400, Math.floor(maxCharacters));
   381|  const chunks: string[] = [];
   382|  for (let index = 0; index < text.length; index += safeMax) {
   383|    chunks.push(text.slice(index, index + safeMax));
   384|  }
   385|  const total = Math.max(1, chunks.length);
   386|  return (chunks.length > 0 ? chunks : ['']).map((chunk, index) => ({
   387|    index: index + 1,
   388|    total,
   389|    characters: chunk.length,
   390|    text: chunk,
   391|  }));
   392|}
