   394|function dashboardProof(inspections: IVXRuntimeV2SourceInspection[]): IVXRuntimeV2ExecutionProof['dashboard'] {
   395|  const dashboard = evidenceFor(inspections, 'cto-dashboard.tsx');
   396|  return {
   397|    file: 'expo/app/ivx/cto-dashboard.tsx',
   398|    cardFound: dashboard.hasIVXAIStatusCard === true,
   399|    runtimeV2TileFound: dashboard.hasRuntimeV2Tile === true,
   400|    liveActivityTileFound: dashboard.hasLiveActivityTile === true,
   401|    testIds: ['cto-ivx-ai-status-card', 'cto-status-runtime-v2', 'cto-status-live-activity', 'cto-status-agent-runtime'],
   402|  };
   403|}
