   405|export async function executeIVXAgentRuntimeV2Loop(input: ExecuteInput): Promise<IVXRuntimeV2ExecutionProof> {
   406|  const prompt = input.prompt.trim();
   407|  if (!prompt) {
   408|    throw new Error('Runtime v2 execution prompt is required.');
   409|  }
   410|
   411|  const jobId = makeJobId();
   412|
   413|  // ── Pre-Execution Feasibility Gate (truth-first) ─────────────────────
   414|  // Runs BEFORE any tool execution, patch, commit, deploy, migration, or
   415|  // proof claim. If any required capability cannot be exercised right now,
   416|  // the loop refuses to execute and returns the exact blocker. No fake
   417|  // reports, no looping, no continuation.
   418|  const feasibilityGate: FeasibilityGateResult = await runPreExecutionFeasibilityGate({
   419|    prompt,
   420|    taskId: jobId,
   421|    ownerSessionPresent: true, // the execution loop is owner-initiated
   422|  });
   423|  if (feasibilityGate.state === 'BLOCKED') {
   424|    const blockerBlock = formatFeasibilityGateBlock(feasibilityGate);
   425|    const blockedProof: IVXRuntimeV2ExecutionProof = {
   426|      ok: false,
   427|      marker: IVX_RUNTIME_V2_EXECUTION_LOOP_MARKER,
   428|      runtimeMarker: IVX_AGENT_RUNTIME_V2_MARKER,
   429|      jobId,
   430|      prompt,
   431|      safeMode: {
   432|        nonDestructive: true,
   433|        productionDataMutated: false,
   434|        deployed: false,
   435|        allowedTools: [],
   436|      },
   437|      phases: ['failed'],
   438|      retry: { enabled: true, maxAttempts: 0, failedStep: 'pre_execution_feasibility_gate', attempts: 0, recovered: false, error: feasibilityGate.exactBlocker },
   439|      memoryState: { stored: false, store: 'local_audit_file_and_in_process_agent_memory', memoryKey: '', loadedEntries: 0, persistedAuditFile: '', persistedJsonlFile: '' },
   440|      planner: buildIVXAgentRuntimeV2Envelope({ requestId: jobId, conversationId: 'runtime-v2-local-audit', prompt, recentMessages: [] }).planner,
   441|      taskTree: { root: { id: 'runtime-v2-root', parentId: null, title: 'Pre-execution feasibility gate blocked execution', ownerGoal: prompt, assignedAgent: 'cto_orchestrator', status: 'blocked', risk: 'high', approvalRequired: true, toolMode: 'none', retryable: false, children: [] }, flat: [] },
   442|      worker: { id: '', agent: 'cto_orchestrator', executedSteps: [] },
   443|      toolChain: [],
   444|      sourceInspections: [],
   445|      dashboard: { file: 'expo/app/ivx/cto-dashboard.tsx', cardFound: false, runtimeV2TileFound: false, liveActivityTileFound: false, testIds: [] },
   446|      streaming: { supported: true, mode: 'chunked_response_contract', shouldChunk: false, maxChunkCharacters: 6_000, estimatedChunks: 0, reason: 'Pre-execution feasibility gate blocked execution; no chunks produced.', actualChunkCharacters: 0, chunks: [] },
   447|      findings: [],
   448|      finalResult: blockerBlock,
   449|      logs: [{ sequence: 1, at: new Date().toISOString(), phase: 'failed', level: 'error', message: `Pre-execution feasibility gate BLOCKED: ${feasibilityGate.blockerCode}`, metadata: { blockerCode: feasibilityGate.blockerCode, exactBlocker: feasibilityGate.exactBlocker, failedCapability: feasibilityGate.failedCapability } }],
   450|      auditFiles: { json: '', jsonl: '' },
   451|      generatedAt: new Date().toISOString(),
   452|    };
   453|    return blockedProof;
   454|  }
   455|  const workerId = `${IVX_RUNTIME_V2_EXECUTION_LOOP_MARKER}:${jobId.slice(-8)}`;
   456|  const conversationId = input.conversationId ?? 'runtime-v2-local-audit';
   457|  const logs: IVXRuntimeV2ExecutionLog[] = [];
   458|  const phases: IVXRuntimeV2ExecutionPhase[] = [];
   459|  const auditDir = path.join(process.cwd(), 'logs', 'audit');
   460|  const jsonPath = path.join(auditDir, `${jobId}.json`);
   461|  const jsonlPath = path.join(auditDir, `${jobId}.jsonl`);
   462|
   463|  const log = (phase: IVXRuntimeV2ExecutionPhase, level: IVXRuntimeV2ExecutionLog['level'], message: string, metadata: Record<string, unknown> = {}): void => {
   464|    phases.push(phase);
   465|    logs.push({ sequence: logs.length + 1, at: nowIso(), phase, level, message, metadata });
   466|  };
   467|
   468|  log('queued', 'info', 'Runtime v2 safe execution job queued.', { jobId, prompt, nonDestructive: true });
   469|
   470|  const plannerDecision = buildIVXOwnerAIPlannerDecision(prompt);
